/**
 * Static course content.
 *
 * The published catalog (courses + categories + published chapters and all of
 * their nested lesson material) is now shipped as checked-in JSON files under
 * `content/`, generated by `scripts/export-content.mjs`. Importing them here —
 * rather than reading them with fs at request time — is required so Vercel's
 * serverless bundler picks the files up and inlines them into the deploy.
 *
 * These types are structurally compatible with the Prisma models they replace
 * on the read-only catalog paths (Course, Category, Chapter and their nested
 * relations). Only the per-user state (progress, purchases, attempts,
 * submissions) still lives in the database.
 */

import categoriesData from "@/content/categories.json";
import coursesData from "@/content/courses.json";
import type { Difficulty, DsaTopic } from "@/lib/coding/types";

