// ---------------------------------------------------------------------------
// Conversion helpers: the JSON files store dates as ISO strings; consumers call
// `.getTime()`, so we turn them back into Date instances at load time.
// ---------------------------------------------------------------------------

const toDate = (value: string): Date => new Date(value);

// Raw (serialized) shapes — dates are strings; everything else mirrors the
// typed interfaces above.
interface RawCategory {
  id: string;
  name: string;
}
interface RawAttachment {
  id: string;
  name: string;
  url: string;
  courseId: string;
  createdAt: string;
  updatedAt: string;
}
interface RawMuxData {
  id: string;
  assetId: string;
  playbackId: string | null;
  chapterId: string;
}
interface RawVideoSource {
  id: string;
  src: string;
  title: string | null;
  position: number;
  chapterId: string;
  createdAt: string;
  updatedAt: string;
}
interface RawPdfNote {
  id: string;
  title: string;
  url: string;
  position: number;
  chapterId: string;
  createdAt: string;
  updatedAt: string;
}
interface RawLeetCodeQuestion {
  id: string;
  title: string;
  url: string | null;
  difficulty: string;
  tags: string | null;
  notes: string | null;
  position: number;
  problemStatement: string | null;
  testCases: string | null;
  solution: string | null;
  chapterId: string;
  createdAt: string;
  updatedAt: string;
}
interface RawTestCase {
  id: string;
  problemId: string;
  input: string;
  expectedOutput: string;
  explanation: string | null;
  isHidden: boolean;
  order: number;
  createdAt: string;
}
interface RawCodingProblem {
  id: string;
  chapterId: string | null;
  testId: string | null;
  title: string;
  difficulty: string;
  topic: string;
  description: string;
  constraints: string | null;
  solution: string | null;
  starterCode: string;
  driverCode: string | null;
  timeLimitMs: number;
  position: number;
  createdAt: string;
  updatedAt: string;
  testCases: RawTestCase[];
}
interface RawChapter {
  id: string;
  title: string;
  description: string | null;
  videoUrl: string | null;
  position: number;
  isPublished: boolean;
  isFree: boolean;
  parentId: string | null;
  courseId: string;
  createdAt: string;
  updatedAt: string;
  muxData: RawMuxData | null;
  videoSources: RawVideoSource[];
  pdfNotes: RawPdfNote[];
  leetcodeQuestions: RawLeetCodeQuestion[];
  codingProblems: RawCodingProblem[];
}
interface RawCourse {
  id: string;
  userId: string;
  title: string;
  description: string | null;
  imageUrl: string | null;
  price: number | null;
  isPublished: boolean;
  categoryId: string | null;
  createdAt: string;
  updatedAt: string;
  category: RawCategory | null;
  attachments: RawAttachment[];
  chapters: RawChapter[];
}

const parseCategory = (raw: RawCategory | null): StaticCategory | null =>
  raw ? { id: raw.id, name: raw.name } : null;

const parseTestCase = (raw: RawTestCase): StaticTestCase => ({
  id: raw.id,
  problemId: raw.problemId,
  input: raw.input,
  expectedOutput: raw.expectedOutput,
  explanation: raw.explanation,
  isHidden: raw.isHidden,
  order: raw.order,
  createdAt: toDate(raw.createdAt),
});

const parseCodingProblem = (raw: RawCodingProblem): StaticCodingProblem => ({
  id: raw.id,
  chapterId: raw.chapterId,
  testId: raw.testId,
  title: raw.title,
  difficulty: raw.difficulty,
  topic: raw.topic,
  description: raw.description,
  constraints: raw.constraints,
  solution: raw.solution,
  starterCode: raw.starterCode,
  driverCode: raw.driverCode,
  timeLimitMs: raw.timeLimitMs,
  position: raw.position,
  createdAt: toDate(raw.createdAt),
  updatedAt: toDate(raw.updatedAt),
  testCases: raw.testCases.map(parseTestCase),
});

const parseChapter = (raw: RawChapter): StaticChapter => ({
  id: raw.id,
  title: raw.title,
  description: raw.description,
  videoUrl: raw.videoUrl,
  position: raw.position,
  isPublished: raw.isPublished,
  isFree: raw.isFree,
  parentId: raw.parentId,
  courseId: raw.courseId,
  createdAt: toDate(raw.createdAt),
  updatedAt: toDate(raw.updatedAt),
  muxData: raw.muxData
    ? {
        id: raw.muxData.id,
        assetId: raw.muxData.assetId,
        playbackId: raw.muxData.playbackId,
        chapterId: raw.muxData.chapterId,
      }
    : null,
  videoSources: raw.videoSources.map((v) => ({
    id: v.id,
    src: v.src,
    title: v.title,
    position: v.position,
    chapterId: v.chapterId,
    createdAt: toDate(v.createdAt),
    updatedAt: toDate(v.updatedAt),
  })),
  pdfNotes: raw.pdfNotes.map((p) => ({
    id: p.id,
    title: p.title,
    url: p.url,
    position: p.position,
    chapterId: p.chapterId,
    createdAt: toDate(p.createdAt),
    updatedAt: toDate(p.updatedAt),
  })),
  leetcodeQuestions: raw.leetcodeQuestions.map((q) => ({
    id: q.id,
    title: q.title,
    url: q.url,
    difficulty: q.difficulty,
    tags: q.tags,
    notes: q.notes,
    position: q.position,
    problemStatement: q.problemStatement,
    testCases: q.testCases,
    solution: q.solution,
    chapterId: q.chapterId,
    createdAt: toDate(q.createdAt),
    updatedAt: toDate(q.updatedAt),
  })),
  codingProblems: raw.codingProblems.map(parseCodingProblem),
});

const parseCourse = (raw: RawCourse): StaticCourse => ({
  id: raw.id,
  userId: raw.userId,
  title: raw.title,
  description: raw.description,
  imageUrl: raw.imageUrl,
  price: raw.price,
  isPublished: raw.isPublished,
  categoryId: raw.categoryId,
  createdAt: toDate(raw.createdAt),
  updatedAt: toDate(raw.updatedAt),
  category: parseCategory(raw.category),
  attachments: raw.attachments.map((a) => ({
    id: a.id,
    name: a.name,
    url: a.url,
    courseId: a.courseId,
    createdAt: toDate(a.createdAt),
    updatedAt: toDate(a.updatedAt),
  })),
  chapters: raw.chapters.map(parseChapter),
});

// ---------------------------------------------------------------------------
// Loaded static data. The JSON is generated from the live DB, so it already
// reflects the published catalog (isPublished === true, chapters ordered by
// position). We still filter defensively to mirror the old query semantics.
// ---------------------------------------------------------------------------

const rawCourses = coursesData as unknown as RawCourse[];
const rawCategories = categoriesData as unknown as RawCategory[];

export const staticCategories: StaticCategory[] = rawCategories.map((c) =>
  parseCategory(c)!,
);

export const staticCourses: StaticCourse[] = rawCourses
  .filter((c) => c.isPublished)
  .filter((c) => Array.isArray(c.chapters))
  .map(parseCourse);

// ---------------------------------------------------------------------------
// Lookup helpers for the student-facing course / chapter / problem pages.
// ---------------------------------------------------------------------------

export function findStaticCourse(courseId: string): StaticCourse | undefined {
  return staticCourses.find((c) => c.id === courseId);
}

export function findStaticChapter(
  courseId: string,
  chapterId: string,
): StaticChapter | undefined {
  return findStaticCourse(courseId)?.chapters.find((ch) => ch.id === chapterId);
}

/**
 * A coding problem serialized for the in-browser workspace: dates stripped,
 * test cases filtered to the public ones (hidden cases are only fetched by the
 * submit endpoint), ordered by `order`.
 */
export interface PublicTestCase {
  id: string;
  input: string;
  expectedOutput: string;
  explanation: string | null;
  isHidden: boolean;
  order: number;
}

export interface CodingProblemView {
  id: string;
  chapterId: string;
  title: string;
  difficulty: Difficulty;
  topic: DsaTopic;
  description: string;
  constraints: string | null;
  solution: string | null;
  starterCode: string;
  driverCode: string | null;
  timeLimitMs: number;
  position: number;
  testCases: PublicTestCase[];
}

function serializeCodingProblem(p: StaticCodingProblem): CodingProblemView {
  return {
    id: p.id,
    chapterId: p.chapterId ?? "",
    title: p.title,
    difficulty: p.difficulty as Difficulty,
    topic: p.topic as DsaTopic,
    description: p.description,
    constraints: p.constraints,
    solution: p.solution,
    starterCode: p.starterCode,
    driverCode: p.driverCode,
    timeLimitMs: p.timeLimitMs,
    position: p.position,
    testCases: p.testCases
      .filter((tc) => !tc.isHidden)
      .sort((a, b) => a.order - b.order)
      .map((tc) => ({
        id: tc.id,
        input: tc.input,
        expectedOutput: tc.expectedOutput,
        explanation: tc.explanation,
        isHidden: tc.isHidden,
        order: tc.order,
      })),
  };
}

/** Coding problems attached to a chapter, ordered by position (public cases only). */
export function getChapterCodingProblems(chapterId: string): CodingProblemView[] {
  const chapter = staticCourses
    .flatMap((c) => c.chapters)
    .find((ch) => ch.id === chapterId);
  if (!chapter) return [];
  return chapter.codingProblems
    .slice()
    .sort((a, b) => a.position - b.position)
    .map(serializeCodingProblem);
}

/** Find a single coding problem by id (public cases only). */
export function findCodingProblem(problemId: string): CodingProblemView | undefined {
  for (const c of staticCourses) {
    for (const ch of c.chapters) {
      const p = ch.codingProblems.find((item) => item.id === problemId);
      if (p) return serializeCodingProblem(p);
    }
  }
  return undefined;
}

// Shapes used by the course sidebar/navbar (static content + per-user progress).
export interface ChapterProgressState {
  isCompleted: boolean;
}

export interface StaticChapterTree extends StaticChapter {
  userProgress: ChapterProgressState[] | null;
  subChapters: (StaticChapter & { userProgress: ChapterProgressState[] | null })[];
}

export interface StaticCourseTree extends StaticCourse {
  chapters: StaticChapterTree[];
}
